package com.gerenciadorrural.modules.herd.application; import com.gerenciadorrural.modules.herd.domain.*; import com.gerenciadorrural.shared.tenancy.*; import org.springframework.stereotype.Service; import java.util.*;
@Service public class TenantTransferLog {private final TenantTransactionExecutor tx;private final HerdTransferRepository transfers;public TenantTransferLog(TenantTransactionExecutor tx,HerdTransferRepository transfers){this.tx=tx;this.transfers=transfers;}public HerdTransferRepository.Page list(TenantContext c,String direction,UUID animal,int page,int size){return tx.execute(c,()->transfers.page(c.tenantId(),c.farmId(),direction,animal,size,(long)page*size));}public HerdTransferRepository.Row detail(TenantContext c,UUID id){return tx.execute(c,()->transfers.detail(c.tenantId(),c.farmId(),id).orElseThrow(HerdAnimalNotFoundException::new));}}
